function fib(n, memo):
  if n in memo:
    return memo[n]
  if n <= 1:
    return n
  memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
  return memo[n]

function climbStairs(n):
  if n <= 2:
    return n
  dp = array(n + 1, 0)
  dp[1] = 1
  dp[2] = 2
  for i in 3..n:
    dp[i] = dp[i - 1] + dp[i - 2]
  return dp[n]

function minCoins(coins, amount):
  dp = array(amount + 1, infinity)
  dp[0] = 0
  for a in 1..amount:
    for coin in coins:
      if coin <= a:
        dp[a] = min(dp[a], dp[a - coin] + 1)
  return dp[amount]

function knapsack(weights, values, capacity):
  n = weights.length
  dp = matrix(n + 1, capacity + 1, 0)
  for i in 1..n:
    for w in 0..capacity:
      if weights[i-1] <= w:
        dp[i][w] = max(dp[i-1][w], values[i-1] + dp[i-1][w-weights[i-1]])
      else:
        dp[i][w] = dp[i-1][w]
  return dp[n][capacity]

function bfsGraph(adj, start):
