function countPaths(grid, r, c, visited):
  if r < 0 or c < 0 or r >= grid.rows or c >= grid.cols:
    return 0
  if grid[r][c] == 1:
    return 0
  if r == grid.rows - 1 and c == grid.cols - 1:
    return 1
  visited.add((r,c))
  paths = countPaths(grid, r+1, c, visited) + countPaths(grid, r, c+1, visited)
  visited.remove((r,c))
  return paths

function lowerBound(arr, target):
  left = 0
  right = arr.length
  while left < right:
    mid = (left + right) / 2
    if arr[mid] < target:
      left = mid + 1
    else:
      right = mid
  return left

function isqrt(n):
  left = 0
  right = n
  while left <= right:
    mid = (left + right) / 2
    if mid * mid == n:
      return mid
    if mid * mid < n:
      left = mid + 1
    else:
      right = mid - 1
  return right

