function dequeue(q):
  if q.outStack is empty:
    while q.inStack not empty:
      q.outStack.push(q.inStack.pop())
  return q.outStack.pop()

function uniquePaths(m, n):
  dp = matrix(m, n, 1)
  for i in 1..m:
    for j in 1..n:
      dp[i][j] = dp[i-1][j] + dp[i][j-1]
  return dp[m-1][n-1]

function canPartition(arr):
  total = sum(arr)
  if total % 2 != 0:
    return false
  target = total / 2
  dp = array(target + 1, false)
  dp[0] = true
  for x in arr:
    for s in target down to x:
      dp[s] = dp[s] or dp[s - x]
  return dp[target]

